import React, { useCallback, useMemo, useState } from 'react';
import {
    Accordion, AccordionDetails, AccordionSummary, Alert, Autocomplete, Badge, Box, Button, Checkbox,
    Chip, CircularProgress, Divider, FormControl, FormControlLabel, Grid, IconButton, InputAdornment,
    InputLabel, MenuItem, Select, Stack, TextField, ToggleButton, ToggleButtonGroup, Typography,
    useMediaQuery, useTheme,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SearchIcon from '@mui/icons-material/Search';
import ClearIcon from '@mui/icons-material/Clear';
import TuneRoundedIcon from '@mui/icons-material/TuneRounded';
import RestartAltIcon from '@mui/icons-material/RestartAlt';
import PersonOutlinedIcon from '@mui/icons-material/PersonOutlined';
import SchoolOutlinedIcon from '@mui/icons-material/SchoolOutlined';
import WorkOutlinedIcon from '@mui/icons-material/WorkOutlined';
import PlaceOutlinedIcon from '@mui/icons-material/PlaceOutlined';
import StorefrontOutlinedIcon from '@mui/icons-material/StorefrontOutlined';
import MyLocationIcon from '@mui/icons-material/MyLocation';
import SearchOffIcon from '@mui/icons-material/SearchOff';

import { AdvancedSearchServices, AdvancedSearchServicesError } from '@/api';
import { AppDialog } from '@/components/ui/AppDialog';
import { EmptyState } from '@/components/ui/EmptyState';
import { SectionHeading } from '@/components/ui/Typography';
import { StatusMessage } from '@/components/StatusMessage';
import { InfiniteScrollList } from '@/components/InfiniteScrollList';
import { BusinessCard } from '@/components/BusinessCard';
import { PersonDisplay } from './PersonDisplay';
import { Schools } from '@/constants/StaticData';
import { BusinessCategories } from '@/constants/StaticLists';
import { CallStatus, Gender, ProfileType, SchoolData } from '@/types/api.types';
import { PublicProfileResult } from '@/types/profile.types';
import { BusinessResult } from '@/types/business.types';
import {
    AdvancedSearchPayload, AdvancedSearchResultData, AdvancedSearchSort, AdvancedSearchTarget,
} from '@/types/advancedSearch.types';
import { useGeolocation } from '@/hooks/useGeolocation';
import { getApiError } from '@/utils/apiError';

const PAGE_SIZE = 20;
const FIRST_BATCH_YEAR = 1985;
const RADIUS_OPTIONS = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 5000];
/** Payload keys that shape the response rather than narrow it. */
const NON_FILTER_KEYS = ['include', 'sortBy', 'sortDescending', 'pageNumber', 'pageSize'];

/** Tri-state selector value: '' = any, 'true' / 'false' = explicit. */
type TriState = '' | 'true' | 'false';

const toBool = (v: TriState): boolean | undefined => (v === '' ? undefined : v === 'true');
const toNumber = (v: string): number | undefined => {
    const n = Number(v);
    return v.trim().length > 0 && Number.isFinite(n) ? n : undefined;
};
const toText = (v: string): string | undefined => (v.trim().length > 0 ? v.trim() : undefined);

const batchYears = Array.from(
    { length: new Date().getFullYear() - FIRST_BATCH_YEAR + 1 },
    (_, i) => FIRST_BATCH_YEAR + i,
);

/** Backend stores the school as a single "JNV <name> <statePrefix>" string. */
const toSchoolName = (s: SchoolData): string => `JNV ${s.SchoolName} ${s.StatePrefix}`;

const initialFilters = {
    name: '',
    location: '',
    organisation: '',
    jobTitle: '',
    university: '',
    degree: '',
    gender: '',
    email: '',
    phone: '',
    profileTypes: [] as string[],
    schools: [] as SchoolData[],
    batchFrom: '',
    batchTo: '',
    entryYearFrom: '',
    entryYearTo: '',
    exitYearFrom: '',
    exitYearTo: '',
    isWorking: '' as TriState,
    isStudying: '' as TriState,
    hasPhoto: '' as TriState,
    hasContactVisible: '' as TriState,
    useNearby: false,
    radiusKm: 10,
    businessText: '',
    businessCategories: [] as string[],
    businessLocation: '',
    pinCode: '',
    hasOffer: '' as TriState,
    include: 'Both' as AdvancedSearchTarget,
    sortBy: 'Relevance' as AdvancedSearchSort,
    sortDescending: false,
};

type Filters = typeof initialFilters;
type FilterKey = keyof Filters;

const TriSelect: React.FC<{ label: string; value: TriState; onChange: (v: TriState) => void }> = ({ label, value, onChange }) => (
    <FormControl fullWidth size="small">
        <InputLabel>{label}</InputLabel>
        <Select label={label} value={value} onChange={(e) => onChange(e.target.value as TriState)}>
            <MenuItem value="">Any</MenuItem>
            <MenuItem value="true">Yes</MenuItem>
            <MenuItem value="false">No</MenuItem>
        </Select>
    </FormControl>
);

const YearSelect: React.FC<{ label: string; value: string; disabled?: boolean; onChange: (v: string) => void }> = ({ label, value, disabled, onChange }) => (
    <FormControl fullWidth size="small" disabled={disabled}>
        <InputLabel>{label}</InputLabel>
        <Select label={label} value={value} onChange={(e) => onChange(String(e.target.value))}>
            <MenuItem value="">Any</MenuItem>
            {batchYears.map((y) => <MenuItem key={y} value={String(y)}>{y}</MenuItem>)}
        </Select>
    </FormControl>
);

const AdvancedSearch: React.FunctionComponent = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

    const [keywords, setKeywords] = useState('');
    const [filters, setFilters] = useState<Filters>(initialFilters);
    // Dialog edits a draft copy so Cancel discards cleanly.
    const [draft, setDraft] = useState<Filters>(initialFilters);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [expanded, setExpanded] = useState<string | false>('person');

    const [status, setStatus] = useState<CallStatus>(CallStatus.NotStarted);
    const [error, setError] = useState<string | undefined>(undefined);
    const [correlationId, setCorrelationId] = useState<string | undefined>(undefined);

    const [profiles, setProfiles] = useState<PublicProfileResult[]>([]);
    const [businesses, setBusinesses] = useState<BusinessResult[]>([]);
    const [profileTotal, setProfileTotal] = useState(0);
    const [businessTotal, setBusinessTotal] = useState(0);
    const [hasMore, setHasMore] = useState(false);
    const [pageNumber, setPageNumber] = useState(1);
    const [loadingMore, setLoadingMore] = useState(false);
    const [lastPayload, setLastPayload] = useState<AdvancedSearchPayload | null>(null);

    const geo = useGeolocation();

    const setDraftValue = useCallback(<K extends FilterKey>(key: K, value: Filters[K]) => {
        setDraft((prev) => ({ ...prev, [key]: value }));
    }, []);

    const buildPayload = useCallback((f: Filters, text: string, page: number): AdvancedSearchPayload => {
        const nearbyReady = f.useNearby && geo.coords.latitude !== 0 && geo.coords.longitude !== 0;
        return {
            text: toText(text),
            name: toText(f.name),
            location: toText(f.location),
            organisation: toText(f.organisation),
            jobTitle: toText(f.jobTitle),
            university: toText(f.university),
            degree: toText(f.degree),
            gender: toText(f.gender),
            email: toText(f.email),
            phone: toText(f.phone),
            profileTypes: f.profileTypes.length > 0 ? f.profileTypes : undefined,
            schoolNames: f.schools.length > 0 ? f.schools.map(toSchoolName) : undefined,
            batchFrom: toNumber(f.batchFrom),
            batchTo: toNumber(f.batchTo),
            entryYearFrom: toNumber(f.entryYearFrom),
            entryYearTo: toNumber(f.entryYearTo),
            exitYearFrom: toNumber(f.exitYearFrom),
            exitYearTo: toNumber(f.exitYearTo),
            isWorking: toBool(f.isWorking),
            isStudying: toBool(f.isStudying),
            hasPhoto: toBool(f.hasPhoto),
            hasContactVisible: toBool(f.hasContactVisible),
            lat: nearbyReady ? geo.coords.latitude : undefined,
            lng: nearbyReady ? geo.coords.longitude : undefined,
            radiusKm: nearbyReady ? f.radiusKm : undefined,
            businessText: toText(f.businessText),
            businessCategories: f.businessCategories.length > 0 ? f.businessCategories : undefined,
            businessLocation: toText(f.businessLocation),
            pinCode: toNumber(f.pinCode),
            hasOffer: toBool(f.hasOffer),
            include: f.include,
            sortBy: f.sortBy,
            sortDescending: f.sortDescending,
            pageNumber: page,
            pageSize: PAGE_SIZE,
        };
    }, [geo.coords.latitude, geo.coords.longitude]);

    // Removable summary chips for everything currently narrowing the search.
    const activeChips = useMemo(() => {
        const f = filters;
        const chips: Array<{ key: string; label: string; reset: () => void }> = [];
        const textChip = (key: FilterKey, label: string, value: string) => {
            if (value.trim()) chips.push({ key, label: `${label}: ${value.trim()}`, reset: () => setFilters((p) => ({ ...p, [key]: '' })) });
        };
        const triChip = (key: FilterKey, label: string, value: TriState) => {
            if (value) chips.push({ key, label: `${label}: ${value === 'true' ? 'Yes' : 'No'}`, reset: () => setFilters((p) => ({ ...p, [key]: '' })) });
        };

        textChip('name', 'Name', f.name);
        textChip('gender', 'Gender', f.gender);
        textChip('location', 'Location', f.location);
        textChip('organisation', 'Organisation', f.organisation);
        textChip('jobTitle', 'Job title', f.jobTitle);
        textChip('university', 'University', f.university);
        textChip('degree', 'Degree', f.degree);
        textChip('email', 'Email', f.email);
        textChip('phone', 'Phone', f.phone);
        if (f.profileTypes.length > 0) chips.push({ key: 'profileTypes', label: `Type: ${f.profileTypes.join(', ')}`, reset: () => setFilters((p) => ({ ...p, profileTypes: [] })) });
        if (f.schools.length > 0) chips.push({ key: 'schools', label: `School: ${f.schools.map((s) => s.SchoolName).join(', ')}`, reset: () => setFilters((p) => ({ ...p, schools: [] })) });
        if (f.batchFrom || f.batchTo) chips.push({ key: 'batch', label: `Batch: ${f.batchFrom || 'any'}–${f.batchTo || 'any'}`, reset: () => setFilters((p) => ({ ...p, batchFrom: '', batchTo: '' })) });
        if (f.entryYearFrom || f.entryYearTo) chips.push({ key: 'entry', label: `Entry: ${f.entryYearFrom || 'any'}–${f.entryYearTo || 'any'}`, reset: () => setFilters((p) => ({ ...p, entryYearFrom: '', entryYearTo: '' })) });
        if (f.exitYearFrom || f.exitYearTo) chips.push({ key: 'exit', label: `Exit: ${f.exitYearFrom || 'any'}–${f.exitYearTo || 'any'}`, reset: () => setFilters((p) => ({ ...p, exitYearFrom: '', exitYearTo: '' })) });
        triChip('isWorking', 'Working', f.isWorking);
        triChip('isStudying', 'Studying', f.isStudying);
        triChip('hasPhoto', 'Has photo', f.hasPhoto);
        triChip('hasContactVisible', 'Contact public', f.hasContactVisible);
        if (f.useNearby) chips.push({ key: 'nearby', label: `Within ${f.radiusKm} km`, reset: () => setFilters((p) => ({ ...p, useNearby: false })) });
        textChip('businessText', 'Business', f.businessText);
        if (f.businessCategories.length > 0) chips.push({ key: 'businessCategories', label: `Category: ${f.businessCategories.join(', ')}`, reset: () => setFilters((p) => ({ ...p, businessCategories: [] })) });
        textChip('businessLocation', 'Business address', f.businessLocation);
        textChip('pinCode', 'PIN', f.pinCode);
        triChip('hasOffer', 'Has offer', f.hasOffer);
        if (f.include !== 'Both') chips.push({ key: 'include', label: `Only ${f.include === 'Profiles' ? 'alumni' : 'businesses'}`, reset: () => setFilters((p) => ({ ...p, include: 'Both' })) });
        if (f.sortBy !== 'Relevance') chips.push({ key: 'sortBy', label: `Sort: ${f.sortBy}${f.sortDescending ? ' desc' : ''}`, reset: () => setFilters((p) => ({ ...p, sortBy: 'Relevance', sortDescending: false })) });

        return chips;
    }, [filters]);

    const filterCount = useMemo(() => {
        const p = buildPayload(filters, '', 1);
        const skip = new Set([...NON_FILTER_KEYS, 'text', 'lng', 'radiusKm']);
        return Object.entries(p).filter(([k, v]) => !skip.has(k) && v !== undefined).length;
    }, [buildPayload, filters]);

    const runSearch = useCallback(async (f: Filters, text: string) => {
        const payload = buildPayload(f, text, 1);
        const hasCriteria = Object.entries(payload).some(([k, v]) => !NON_FILTER_KEYS.includes(k) && v !== undefined);
        if (!hasCriteria) {
            setError('Enter a keyword or add at least one filter before searching.');
            setStatus(CallStatus.Failure);
            return;
        }

        setStatus(CallStatus.InProgress);
        setError(undefined);
        setCorrelationId(undefined);
        setLastPayload(payload);
        setPageNumber(1);

        try {
            const response = await AdvancedSearchServices.Search(payload);
            if (response.data.status >= 200 && response.data.status < 300) {
                const result: AdvancedSearchResultData = response.data.result;
                setProfiles(result.profiles?.items ?? []);
                setBusinesses(result.businesses?.items ?? []);
                setProfileTotal(result.profileTotalCount ?? 0);
                setBusinessTotal(result.businessTotalCount ?? 0);
                setHasMore((result.profiles?.hasNextPage ?? false) || (result.businesses?.hasNextPage ?? false));
                setStatus(CallStatus.Success);
            } else {
                setError(AdvancedSearchServicesError.AdvancedSearchError(response.data.status));
                setProfiles([]);
                setBusinesses([]);
                setHasMore(false);
                setStatus(CallStatus.Failure);
            }
        } catch (err) {
            const apiErr = getApiError(err);
            setError(AdvancedSearchServicesError.AdvancedSearchError(apiErr.httpStatus));
            setCorrelationId(apiErr.correlationId);
            setProfiles([]);
            setBusinesses([]);
            setHasMore(false);
            setStatus(CallStatus.Failure);
        }
    }, [buildPayload]);

    const loadMore = useCallback(async () => {
        if (loadingMore || !hasMore || !lastPayload) return;
        setLoadingMore(true);
        const nextPage = pageNumber + 1;
        try {
            const response = await AdvancedSearchServices.Search({ ...lastPayload, pageNumber: nextPage });
            if (response.data.status >= 200 && response.data.status < 300) {
                const result: AdvancedSearchResultData = response.data.result;
                setProfiles((prev) => [...prev, ...(result.profiles?.items ?? [])]);
                setBusinesses((prev) => [...prev, ...(result.businesses?.items ?? [])]);
                setHasMore((result.profiles?.hasNextPage ?? false) || (result.businesses?.hasNextPage ?? false));
                setPageNumber(nextPage);
            }
        } catch {
            // Silently fail; scrolling again retries.
        } finally {
            setLoadingMore(false);
        }
    }, [loadingMore, hasMore, lastPayload, pageNumber]);

    const clearAll = useCallback(() => {
        setKeywords('');
        setFilters(initialFilters);
        setDraft(initialFilters);
        setProfiles([]);
        setBusinesses([]);
        setProfileTotal(0);
        setBusinessTotal(0);
        setHasMore(false);
        setPageNumber(1);
        setLastPayload(null);
        setError(undefined);
        setStatus(CallStatus.NotStarted);
    }, []);

    const openDialog = () => { setDraft(filters); setDialogOpen(true); };
    const applyDialog = () => { setFilters(draft); setDialogOpen(false); runSearch(draft, keywords); };

    const isSearching = status === CallStatus.InProgress;
    const showProfiles = filters.include !== 'Businesses';
    const showBusinesses = filters.include !== 'Profiles';
    const hasResults = profiles.length > 0 || businesses.length > 0;
    const isPristine = status === CallStatus.NotStarted && !hasResults;
    const section = (key: string) => ({
        expanded: expanded === key,
        onChange: (_e: React.SyntheticEvent, open: boolean) => setExpanded(open ? key : false),
    });

    return (
        <Box sx={{ maxWidth: 720, mx: 'auto', px: { xs: 1, sm: 2 } }}>
            <Box sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                pt: isPristine ? 4 : 1,
                pb: 2,
                transition: 'padding 0.3s ease',
            }}>
                {isPristine && (
                    <Typography
                        variant="h4"
                        sx={{
                            fontWeight: 700,
                            mb: 3,
                            background: 'linear-gradient(135deg, #1976d2 0%, #42a5f5 50%, #1565c0 100%)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            letterSpacing: '-0.5px',
                        }}
                    >
                        Advanced Search
                    </Typography>
                )}

                <Box sx={{ width: '100%', maxWidth: 580, px: isMobile ? 1 : 0 }}>
                    <TextField
                        fullWidth
                        placeholder="Search alumni, businesses…"
                        value={keywords}
                        onChange={(e) => setKeywords(e.target.value)}
                        onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); runSearch(filters, keywords); } }}
                        disabled={isSearching}
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                borderRadius: '24px',
                                height: isMobile ? 48 : 52,
                                px: 1,
                                bgcolor: '#ffffff',
                                border: '1px solid #dfe1e5',
                                boxShadow: 'none',
                                '&:hover': {
                                    bgcolor: '#ffffff',
                                    boxShadow: '0 2px 8px 1px rgba(64,60,67,.16)',
                                    borderColor: 'transparent',
                                },
                                '&.Mui-focused': {
                                    bgcolor: '#ffffff',
                                    boxShadow: '0 2px 8px 1px rgba(64,60,67,.16)',
                                    borderColor: 'transparent',
                                },
                                '& fieldset': { border: 'none' },
                            },
                        }}
                        slotProps={{
                            input: {
                                startAdornment: (
                                    <InputAdornment position="start">
                                        <Badge badgeContent={filterCount} color="error" overlap="circular">
                                            <IconButton
                                                size="small"
                                                onClick={openDialog}
                                                sx={{ color: '#fff', bgcolor: 'primary.main', '&:hover': { bgcolor: 'primary.dark' } }}
                                                title="Filters"
                                            >
                                                <TuneRoundedIcon fontSize="small" />
                                            </IconButton>
                                        </Badge>
                                    </InputAdornment>
                                ),
                                endAdornment: (
                                    <InputAdornment position="end">
                                        {(keywords || filterCount > 0) && (
                                            <IconButton size="small" onClick={clearAll} disabled={isSearching}>
                                                <ClearIcon fontSize="small" />
                                            </IconButton>
                                        )}
                                        {isSearching ? (
                                            <CircularProgress size={20} sx={{ ml: 0.5 }} />
                                        ) : (
                                            <IconButton size="small" color="primary" onClick={() => runSearch(filters, keywords)}>
                                                <SearchIcon />
                                            </IconButton>
                                        )}
                                    </InputAdornment>
                                ),
                            },
                        }}
                    />

                    {activeChips.length > 0 && (
                        <Stack direction="row" spacing={0.5} sx={{ mt: 1.5, flexWrap: 'wrap', gap: 0.5, justifyContent: 'center' }}>
                            {activeChips.map((c) => (
                                <Chip
                                    key={c.key}
                                    size="small"
                                    variant="outlined"
                                    label={c.label}
                                    onDelete={c.reset}
                                    sx={{ fontSize: '0.7rem', height: 24, maxWidth: '100%' }}
                                />
                            ))}
                        </Stack>
                    )}
                </Box>

                {isPristine && (
                    <Typography variant="caption" color="text.secondary" sx={{ mt: 3, textAlign: 'center' }}>
                        Tap the filter icon to combine school, batch, work, location and business filters.
                    </Typography>
                )}
            </Box>

            <StatusMessage
                notStartedMessage=""
                failureMessage={error || 'Advanced search failed. Please try again.'}
                currentStatus={status}
                correlationId={correlationId}
            />

            {status === CallStatus.Success && !hasResults && (
                <EmptyState
                    variant="hint"
                    illustration={<SearchOffIcon sx={{ fontSize: 48 }} />}
                    heading="No matches"
                    helper="No records matched every filter. Try removing one or two of them."
                />
            )}

            {showProfiles && profiles.length > 0 && (
                <>
                    <Box sx={{ px: 0.5, mb: 0.5, mt: 1 }}>
                        <SectionHeading>Alumni ({profileTotal})</SectionHeading>
                    </Box>
                    <InfiniteScrollList
                        items={profiles}
                        loading={loadingMore}
                        hasMore={hasMore}
                        loadMore={loadMore}
                        renderItem={(profile) => <PersonDisplay key={profile.id} {...profile} isAdmin />}
                    />
                </>
            )}

            {showBusinesses && businesses.length > 0 && (
                <>
                    <Box sx={{ px: 0.5, mb: 0.5, mt: 1 }}>
                        <SectionHeading>Businesses ({businessTotal})</SectionHeading>
                    </Box>
                    <InfiniteScrollList
                        items={businesses}
                        loading={loadingMore}
                        hasMore={hasMore}
                        loadMore={loadMore}
                        renderItem={(business) => <BusinessCard key={business.id} {...business} isAdmin />}
                    />
                </>
            )}

            <AppDialog
                open={dialogOpen}
                onClose={() => setDialogOpen(false)}
                title="Filters"
                maxWidth="md"
                actions={
                    <>
                        <Button startIcon={<RestartAltIcon />} color="inherit" onClick={() => setDraft(initialFilters)}>Reset</Button>
                        <Box sx={{ flex: 1 }} />
                        <Button onClick={() => setDialogOpen(false)} color="inherit">Cancel</Button>
                        <Button variant="contained" startIcon={<SearchIcon />} onClick={applyDialog}>Apply &amp; search</Button>
                    </>
                }
            >
                <Accordion disableGutters {...section('person')}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <PersonOutlinedIcon fontSize="small" />
                            <Typography variant="subtitle2">Person</Typography>
                        </Stack>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Grid container spacing={2}>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Name" value={draft.name}
                                    onChange={(e) => setDraftValue('name', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <FormControl fullWidth size="small">
                                    <InputLabel>Gender</InputLabel>
                                    <Select label="Gender" value={draft.gender} onChange={(e) => setDraftValue('gender', String(e.target.value))}>
                                        <MenuItem value="">Any</MenuItem>
                                        {Object.values(Gender).map((g) => <MenuItem key={g} value={g}>{g}</MenuItem>)}
                                    </Select>
                                </FormControl>
                            </Grid>
                            <Grid size={{ xs: 12 }}>
                                <Autocomplete
                                    multiple
                                    size="small"
                                    options={Object.values(ProfileType)}
                                    value={draft.profileTypes}
                                    onChange={(_e, v) => setDraftValue('profileTypes', v)}
                                    renderInput={(params) => <TextField {...params} label="Profile type" />}
                                />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TriSelect label="Has photo" value={draft.hasPhoto} onChange={(v) => setDraftValue('hasPhoto', v)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TriSelect label="Contact info public" value={draft.hasContactVisible} onChange={(v) => setDraftValue('hasContactVisible', v)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Email" value={draft.email}
                                    onChange={(e) => setDraftValue('email', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Phone" value={draft.phone}
                                    onChange={(e) => setDraftValue('phone', e.target.value)} />
                            </Grid>
                        </Grid>
                    </AccordionDetails>
                </Accordion>

                <Accordion disableGutters {...section('school')}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <SchoolOutlinedIcon fontSize="small" />
                            <Typography variant="subtitle2">School &amp; education</Typography>
                        </Stack>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Grid container spacing={2}>
                            <Grid size={{ xs: 12 }}>
                                <Autocomplete
                                    multiple
                                    size="small"
                                    options={Schools}
                                    value={draft.schools}
                                    onChange={(_e, v) => setDraftValue('schools', v as SchoolData[])}
                                    getOptionLabel={(o) => `[${o.StatePrefix}] ${o.SchoolName}`}
                                    isOptionEqualToValue={(a, b) => a.UniqueId === b.UniqueId}
                                    renderInput={(params) => <TextField {...params} label="Schools (JNV)" />}
                                />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <YearSelect label="Batch from" value={draft.batchFrom}
                                    onChange={(v) => setDraftValue('batchFrom', v)} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <YearSelect label="Batch to" value={draft.batchTo}
                                    onChange={(v) => setDraftValue('batchTo', v)} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <YearSelect label="Entry from" value={draft.entryYearFrom}
                                    onChange={(v) => setDraftValue('entryYearFrom', v)} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <YearSelect label="Entry to" value={draft.entryYearTo}
                                    onChange={(v) => setDraftValue('entryYearTo', v)} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <YearSelect label="Exit from" value={draft.exitYearFrom}
                                    onChange={(v) => setDraftValue('exitYearFrom', v)} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <YearSelect label="Exit to" value={draft.exitYearTo}
                                    onChange={(v) => setDraftValue('exitYearTo', v)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="University" value={draft.university}
                                    onChange={(e) => setDraftValue('university', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Degree" value={draft.degree}
                                    onChange={(e) => setDraftValue('degree', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TriSelect label="Currently studying" value={draft.isStudying} onChange={(v) => setDraftValue('isStudying', v)} />
                            </Grid>
                        </Grid>
                    </AccordionDetails>
                </Accordion>

                <Accordion disableGutters {...section('work')}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <WorkOutlinedIcon fontSize="small" />
                            <Typography variant="subtitle2">Work</Typography>
                        </Stack>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Grid container spacing={2}>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Organisation" value={draft.organisation}
                                    onChange={(e) => setDraftValue('organisation', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Job title" value={draft.jobTitle}
                                    onChange={(e) => setDraftValue('jobTitle', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TriSelect label="Currently working" value={draft.isWorking} onChange={(v) => setDraftValue('isWorking', v)} />
                            </Grid>
                        </Grid>
                    </AccordionDetails>
                </Accordion>

                <Accordion disableGutters {...section('location')}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <PlaceOutlinedIcon fontSize="small" />
                            <Typography variant="subtitle2">Location</Typography>
                        </Stack>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Grid container spacing={2}>
                            <Grid size={{ xs: 12 }}>
                                <TextField fullWidth size="small" label="Location contains" value={draft.location}
                                    onChange={(e) => setDraftValue('location', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12 }}>
                                <FormControlLabel
                                    control={<Checkbox checked={draft.useNearby} onChange={(e) => setDraftValue('useNearby', e.target.checked)} />}
                                    label="Limit to alumni near me"
                                />
                            </Grid>
                            {draft.useNearby && (
                                <>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <FormControl fullWidth size="small">
                                            <InputLabel>Radius</InputLabel>
                                            <Select label="Radius" value={draft.radiusKm} onChange={(e) => setDraftValue('radiusKm', Number(e.target.value))}>
                                                {RADIUS_OPTIONS.map((km) => <MenuItem key={km} value={km}>Within {km} km</MenuItem>)}
                                            </Select>
                                        </FormControl>
                                    </Grid>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <Button
                                            fullWidth
                                            variant="outlined"
                                            startIcon={geo.inProgress ? <CircularProgress size={16} /> : <MyLocationIcon />}
                                            disabled={geo.inProgress}
                                            onClick={geo.request}
                                        >
                                            {geo.coords.latitude !== 0 ? 'Update my location' : 'Use my location'}
                                        </Button>
                                    </Grid>
                                    <Grid size={{ xs: 12 }}>
                                        {geo.error
                                            ? <Alert severity="error">{geo.error}</Alert>
                                            : geo.coords.latitude !== 0 && (
                                                <Typography variant="caption" color="text.secondary">
                                                    Using {geo.coords.latitude.toFixed(4)}, {geo.coords.longitude.toFixed(4)}
                                                </Typography>
                                            )}
                                    </Grid>
                                </>
                            )}
                        </Grid>
                    </AccordionDetails>
                </Accordion>

                <Accordion disableGutters {...section('business')}>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                            <StorefrontOutlinedIcon fontSize="small" />
                            <Typography variant="subtitle2">Business</Typography>
                        </Stack>
                    </AccordionSummary>
                    <AccordionDetails>
                        <Grid container spacing={2}>
                            <Grid size={{ xs: 12 }}>
                                <TextField fullWidth size="small" label="Business keywords" value={draft.businessText}
                                    onChange={(e) => setDraftValue('businessText', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 12 }}>
                                <Autocomplete
                                    multiple
                                    size="small"
                                    options={BusinessCategories}
                                    value={draft.businessCategories}
                                    onChange={(_e, v) => setDraftValue('businessCategories', v)}
                                    renderInput={(params) => <TextField {...params} label="Categories" />}
                                />
                            </Grid>
                            <Grid size={{ xs: 12, sm: 6 }}>
                                <TextField fullWidth size="small" label="Address contains" value={draft.businessLocation}
                                    onChange={(e) => setDraftValue('businessLocation', e.target.value)} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <TextField fullWidth size="small" label="PIN code" value={draft.pinCode}
                                    onChange={(e) => setDraftValue('pinCode', e.target.value.replace(/[^0-9]/g, '').slice(0, 6))} />
                            </Grid>
                            <Grid size={{ xs: 6, sm: 3 }}>
                                <TriSelect label="Has offer" value={draft.hasOffer} onChange={(v) => setDraftValue('hasOffer', v)} />
                            </Grid>
                        </Grid>
                    </AccordionDetails>
                </Accordion>

                <Divider sx={{ my: 2 }} />

                <Grid container spacing={2} sx={{ alignItems: 'center' }}>
                    <Grid size={{ xs: 12, sm: 5 }}>
                        <ToggleButtonGroup
                            size="small"
                            exclusive
                            fullWidth
                            value={draft.include}
                            onChange={(_e, v) => v && setDraftValue('include', v as AdvancedSearchTarget)}
                        >
                            <ToggleButton value="Both">Both</ToggleButton>
                            <ToggleButton value="Profiles">Alumni</ToggleButton>
                            <ToggleButton value="Businesses">Businesses</ToggleButton>
                        </ToggleButtonGroup>
                    </Grid>
                    <Grid size={{ xs: 8, sm: 4 }}>
                        <FormControl fullWidth size="small">
                            <InputLabel>Sort by</InputLabel>
                            <Select label="Sort by" value={draft.sortBy} onChange={(e) => setDraftValue('sortBy', e.target.value as AdvancedSearchSort)}>
                                <MenuItem value="Relevance">Relevance</MenuItem>
                                <MenuItem value="Name">Name</MenuItem>
                                <MenuItem value="Batch">Batch</MenuItem>
                                <MenuItem value="Distance" disabled={!draft.useNearby}>Distance</MenuItem>
                            </Select>
                        </FormControl>
                    </Grid>
                    <Grid size={{ xs: 4, sm: 3 }}>
                        <FormControlLabel
                            control={<Checkbox
                                checked={draft.sortDescending}
                                disabled={draft.sortBy === 'Relevance'}
                                onChange={(e) => setDraftValue('sortDescending', e.target.checked)}
                            />}
                            label="Desc"
                        />
                    </Grid>
                </Grid>
            </AppDialog>
        </Box>
    );
};

export default AdvancedSearch;
